rag_sparql:
PREFIX aib: <http://example.org/ai-news/>
SELECT ?founder WHERE { ?founder aib:foundedBy ?company . 
} LIMIT 1

PREFIX aib: <http://example.org/ai-news/>

SELECT ?company WHERE {
?company aib:locatedIn ?location .
?location wdt:P31 ?usa .

}
LIMIT 20

PREFIX aib: <http://example.org/ai-news/>

SELECT DISTINCT ?person WHERE {
  ?person wdt:P452 ?company .
  FILTER (
    ?company wdt:P31 ?product
    ?product wdt:P108 ?person
    SERVICE wikibase:label { bd:label ?companyLabel . }
  )

}
LIMIT 20
